/* machine-generated by m2c: a starting point, not a match */

extern s8 gVoiceSlotTable;
extern u8 gVoiceIdTable[];

/* Resets all voice slot entries and voice ids to 0xFF (unused). */ void clearVoiceTables(void) {
    char *slotRow;
    char *slotByte;
    u32 row;
    u32 idIndex;
int __repair_constant;

    row = 0;
__repair_constant = 0xFF;
    slotRow = &gVoiceSlotTable;
    do {
        slotByte = slotRow;
do {
        *(s8 *)slotByte = __repair_constant;
        slotByte += 1;
        } while ((u32) slotByte < (u32) (slotRow + 0x10));
        row += 1;
        slotRow += 0x10;
    } while (row < 8U);
    idIndex = 0;
    do {
        *(gVoiceIdTable + idIndex) = 0xFF;/*__repair_loop_weight*/do {
        idIndex += 1;} while (0);
    } while (idIndex < 0x20U);
}
